import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { DATA_DIR, ensureDir, env } from '../config.js';

/**
 * Encrypts secrets stored in the database (AD bind password, SMTP password, …) with
 * AES-256-GCM. The key comes from ENCRYPTION_KEY in .env (generated by the installer);
 * development checkouts without one get a key file in data/.
 */
const DEV_KEY_FILE = path.join(DATA_DIR, 'secret.key');
const PREFIX = 'v1';

let key: Buffer | undefined;

function getKey(): Buffer {
  if (key) return key;
  let encoded = env.encryptionKey;
  if (!encoded) {
    if (!fs.existsSync(DEV_KEY_FILE)) {
      ensureDir(DATA_DIR);
      fs.writeFileSync(DEV_KEY_FILE, crypto.randomBytes(32).toString('base64') + '\n', { mode: 0o600 });
      console.warn(`ENCRYPTION_KEY is not set; generated ${DEV_KEY_FILE}. Set ENCRYPTION_KEY in .env for production.`);
    }
    encoded = fs.readFileSync(DEV_KEY_FILE, 'utf8').trim();
  }
  const buf = Buffer.from(encoded, 'base64');
  if (buf.length !== 32) throw new Error('ENCRYPTION_KEY must be 32 bytes, base64-encoded.');
  key = buf;
  return key;
}

export function encryptSecret(plain: string): string {
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', getKey(), iv);
  const data = Buffer.concat([cipher.update(plain, 'utf8'), cipher.final()]);
  return [PREFIX, iv.toString('base64'), cipher.getAuthTag().toString('base64'), data.toString('base64')].join(':');
}

export function decryptSecret(stored: string): string {
  const [prefix, iv, tag, data] = stored.split(':');
  if (prefix !== PREFIX || !iv || !tag || data === undefined) throw new Error('Unrecognised encrypted value.');
  const decipher = crypto.createDecipheriv('aes-256-gcm', getKey(), Buffer.from(iv, 'base64'));
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(data, 'base64')), decipher.final()]).toString('utf8');
}
